"""Generate deterministic Glass Pop token exports and component documentation."""
from pathlib import Path
import json, colorsys

ROOT = Path(__file__).resolve().parents[1]
levels = [50,100,200,300,400,500,600,700,800,900,950]
colors = {'pink':'FF3DA5','yellow':'FFCC00','sky':'CFEAFF','ice':'DFF5FF','mint':'BDF5E3','lilac':'B7ABF6','lavender':'EDE4FF','blush':'FFE3F0','peach':'FFD5BD','ink':'181820','midnight':'11131D','plum':'21172B','jade':'075B50','white':'FFFFFF','cloud':'F9FAFC','pearl':'FCF8FF','mist':'EEF3F9','soft-ink':'343541','muted':'666879'}
def ramp(hex_value):
    rgb=[int(hex_value[i:i+2],16)/255 for i in (0,2,4)]
    out={}
    for level in levels:
        if level == 500: result=rgb
        elif level < 500:
            amount={50:.94,100:.86,200:.69,300:.48,400:.24}[level]
            result=[c+(1-c)*amount for c in rgb]
        else:
            amount={600:.16,700:.33,800:.52,900:.70,950:.82}[level]
            result=[c*(1-amount) for c in rgb]
        out[str(level)]={'$type':'color','$value':'#'+''.join(f'{round(c*255):02x}' for c in result)}
    return out
tokens={'$description':'Glass Pop 2.0 / graao club. 500 preserves the supplied source color; ramps are sRGB mixtures, not perceptually uniform.', 'color':{k:ramp(v) for k,v in colors.items()},'themes':{},'space':{},'radius':{},'motion':{},'glass':{},'type':{},'zIndex':{},'layout':{}}
for theme,values in {
 'light':{'background':'#f9fafc','canvas':'#fcf8ff','surface':'#ffffff','text':'#181820','text-secondary':'#505260','text-muted':'#666879','accent':'#ff3da5','on-accent':'#181820','accent-text':'#a8005b','success':'#116149','warning':'#785400','danger':'#b82039','info':'#155e92'},
 'dark':{'background':'#11131d','canvas':'#181a27','surface':'#211e30','text':'#fcf8ff','text-secondary':'#d2cede','text-muted':'#aaa6bb','accent':'#ff3da5','on-accent':'#181820','accent-text':'#ff8bca','success':'#91e6be','warning':'#ffda69','danger':'#ff9baa','info':'#9fd8ff'},
 'high-contrast':{'background':'#ffffff','canvas':'#ffffff','surface':'#ffffff','text':'#000000','text-secondary':'#000000','text-muted':'#000000','accent':'#a8005b','on-accent':'#ffffff','accent-text':'#8e004b','success':'#116149','warning':'#785400','danger':'#b82039','info':'#155e92'}}.items():
    tokens['themes'][theme]={k:{'$type':'color','$value':v} for k,v in values.items()}
for size in [4,8,12,16,20,24,32,40,48,64,80,96]: tokens['space'][str(size)]={'$type':'dimension','$value':f'{size}px'}
for key,value in {'xs':8,'sm':12,'md':18,'lg':24,'xl':32,'2xl':44,'pill':999}.items(): tokens['radius'][key]={'$type':'dimension','$value':f'{value}px'}
for name,blur,opacity in [('clear',8,.68),('frosted',20,.82),('milk',32,.94),('dark',24,.92),('liquid',40,.82)]:
    tokens['glass'][name]={'background':'#11131d' if name=='dark' else '#ffffff','opacity':opacity,'blur':f'{blur}px','saturation':'135%','border':'1px solid translucent highlight','highlight':'inset 0 1px rgba(255,255,255,.5)','shadow':'0 20px 60px -24px rgba(52,53,65,.19)','radius':'32px','noise':0,'elevation':2,'refraction':False}
tokens['motion']={'duration':{'feedback':'140ms','hover':'200ms','interface':'320ms','reveal':'640ms','editorial':'800ms'},'delay':'0ms','stagger':'60ms','ease':'cubic-bezier(.16,1,.3,1)','spring':'cubic-bezier(.34,1.56,.64,1)','enter':'opacity 0→1; translateY 16px→0','exit':'opacity 1→0; 140ms','press':'scale(.98)','scroll':'IntersectionObserver; once','reduced':'disable decorative animation and smooth scrolling'}
scales={'display-xl':(56,104),'display-l':(48,88),'display-m':(40,72),'h1':(40,72),'h2':(34,48),'h3':(24,32),'h4':(18,24),'h5':(16,20),'h6':(14,16),'body-xl':(20,24),'body-l':(17,20),'body-m':(15,16),'body-s':(14,14),'label':(13,14),'button':(14,15),'eyebrow':(12,13),'caption':(12,13),'number':(24,72),'microcopy':(12,12)}
for key,(lo,hi) in scales.items():tokens['type'][key]={'$type':'string','$value':f'clamp({lo}px, {round(hi/14.4,2)}vw, {hi}px)'}
tokens['zIndex']={'base':0,'sticky':20,'navigation':50,'popover':100,'modal':200,'toast':300}
tokens['layout']={'columns':{'mobile':4,'tablet':8,'desktop':12},'container':'1240px','gutter':'clamp(16px,3vw,40px)','breakpoints':{'sm':'520px','md':'860px','lg':'1100px','xl':'1360px'}}
(ROOT/'assets/tokens/glass-pop.json').write_text(json.dumps(tokens,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
css=['/* Generated by tools/build_glass_pop.py. Do not edit. */',':root {']
for name,scale in tokens['color'].items():
    for level,entry in scale.items():css.append(f'  --g-pop-{name}-{level}: {entry["$value"]};')
for name,value in tokens['type'].items():css.append(f'  --g-type-{name}: {value["$value"]};')
for name,value in tokens['zIndex'].items():css.append(f'  --g-z-{name}: {value};')
css+=['  --g-layout-gutter: clamp(16px,3vw,40px);','  --g-layout-columns: 12;','}', '@media(max-width:1100px) { :root { --g-layout-columns:8; } }','@media(max-width:520px) { :root { --g-layout-columns:4; } }']
(ROOT/'assets/css/glass-pop-tokens.css').write_text('\n'.join(css)+'\n',encoding='utf-8')

# Apply the compatibility layer after the established styles, preserving each route.
font='https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Sora:wght@400;500;600&family=Anton&display=swap'
for path in ROOT.glob('*.html'):
    html=path.read_text(encoding='utf-8')
    import re
    html=re.sub(r'https://fonts.googleapis.com/css2\?family=Geist[^"\s]+',font,html)
    if 'assets/css/glass-pop.css' not in html:
        matches=list(re.finditer(r'<link rel="stylesheet" href="assets/css/[^"\n]+">',html))
        if matches:
            at=matches[-1].end();html=html[:at]+'\n  <link rel="stylesheet" href="assets/css/glass-pop-tokens.css">\n  <link rel="stylesheet" href="assets/css/glass-pop.css">'+html[at:]
    elif 'assets/css/glass-pop-tokens.css' not in html:
        html=html.replace('<link rel="stylesheet" href="assets/css/glass-pop.css">','<link rel="stylesheet" href="assets/css/glass-pop-tokens.css"><link rel="stylesheet" href="assets/css/glass-pop.css">')
    path.write_text(html,encoding='utf-8')

# Component contracts supplement the existing, preserved live library.
groups={
'Actions': [('Primary','.g-btn--accent'),('Secondary','.g-btn'),('Glass','.g-btn.g-glass'),('Ghost','.g-btn--quiet'),('Highlight','.g-btn--yellow'),('Icon button','.g-icon-btn'),('Destructive','.g-btn--hold[data-g-hold]')],
'Forms':[('Input / textarea / select / date','.g-field'),('Checkbox / radio','.g-check'),('Switch','.g-switch'),('Slider','input[type=range]'),('Upload','input[type=file]'),('Multi-step form','form + fieldset + progress')],
'Navigation':[('Navbar / glass navbar','.g-pop-nav / .g-glass'),('Sidebar','.g-sidenav'),('Tabs','.g-tabs[data-g-tabs]'),('Breadcrumbs','nav[aria-label] + ol'),('Dock / mobile menu','.g-tabbar'),('Context menu','.g-menu')],
'Feedback':[('Alert','.g-card[role=status]'),('Toast','G.toast'),('Loading / skeleton','.g-skeleton'),('Progress','.g-progress / .g-ring'),('Empty state','.g-empty'),('Confirmation','G.modal')],
'Overlays':[('Modal / dialog / drawer','G.modal / G.modal({sheet:true})'),('Popover','.g-popover'),('Tooltip','.g-tooltip[data-tip]'),('Image lightbox','.g-pop-lightbox')],
'Display':[('Card','.g-card'),('Badge','.g-badge'),('Avatar','.g-avatar'),('Accordion','details + summary'),('Table','.g-table'),('List','.g-row'),('Timeline','.flow__steps'),('Indicator','.g-status')],
'Media':[('Editorial Image','.g-pop-art'),('Full Bleed Hero','figure + .g-pop-art'),('Framed Photo','.g-frame'),('Image Stack','.g-stack-cards'),('Photo Collage','.g-pop-grid'),('Image Bento','.g-pop-grid'),('Image Gallery','#g-pop-gallery'),('Masonry Gallery','CSS columns; specification'),('Circular Gallery','React Bits; deferred'),('Horizontal Gallery','.g-scroll--x'),('Image Lightbox','.g-pop-lightbox'),('Image With Glass Overlay','.g-pop-stage + figcaption.g-glass'),('Product Mockup','.g-frame'),('Soft 3D Stage','.g-pop-stage'),('Before/After Image','range + two images; specification'),('Immersive Media Section','figure + .g-noite')],
'Page structures':[('Editorial hero','.g-pop-hero'),('Editorial section','.g-pop-section'),('Bento','.g-pop-grid'),('Dashboard / content area','.g-pop-workspace'),('Footer','.g-pop-footer')]}
lines=['# Glass Pop 2.0 — Catálogo de contratos','', 'As classes existentes continuam na vitrine. “Specification” indica composição documentada ainda sem controlador dedicado. Nenhuma integração React é apresentada como instalada.','']
for group,items in groups.items():
    lines+=['## '+group,'']
    for name,api in items:
        lines += [f'### {name}',f'- **Propósito / API:** {api}; {group.lower()} com hierarquia clara.', '- **Anatomia:** raiz semântica, conteúdo, rótulo acessível, ação ou estado opcional.', '- **Variantes / tamanhos:** Dia, Noite, alto contraste; controles 32/40/52px, toque mínimo 44px; cards 24/32px de padding.', '- **Tokens:** `--g-text`, `--g-text-2`, `--g-surface`, `--g-line`, `--g-accent-text`, espaços e raios `--g-*`.', '- **Estados:** default, hover, focus-visible, active; disabled e erro quando aplicáveis; estado nunca comunicado apenas por cor.', '- **Propriedades:** texto obrigatório, identificação estável; mídia exige alt, dimensões e foco; ações exigem nome e destino ou handler.', '- **Comportamento:** ações explícitas; não iniciar autoplay; estado persistido somente quando informado; exclusão exige confirmação ou desfazer.', '- **Responsividade:** conteúdo reflow em 320px; uma coluna abaixo de 520px, grids por conteúdo; nenhuma informação exclusiva de hover.', '- **Acessibilidade:** HTML nativo primeiro, teclado e foco visível, status anunciado sem roubar foco; overlay exige Escape, contenção e retorno do foco.', f'- **Exemplo / evidência:** `design-system.html` para componentes herdados; `glass-pop.html` para materiais, filtros, lightbox e planejamento. `{api}` é o ponto de composição.', '']
(ROOT/'docs/GLASS_POP_COMPONENTS.md').write_text('\n'.join(lines),encoding='utf-8')
print('Generated tokens, CSS ramps, component contracts and page stylesheet links.')
